export const categories={receita:['Salário','Freelance','Rendimentos','Outras receitas'],despesa:['Moradia','Alimentação','Transporte','Saúde','Educação','Lazer','Assinaturas','Impostos e tarifas','Parcelas e financiamentos','Consórcios','Outras despesas'],transferencia:['Transferência entre contas']};
export const accounts=['Conta principal','Carteira','Reserva'];
export const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Fortaleza',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
export const money=c=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(c/100);
export function cents(v){if(typeof v==='number'){if(!Number.isFinite(v)||v<0||v>1e10)throw Error('Valor inválido');return Math.round(v*100);}let s=String(v??'').trim().replace(/R\$|\s/g,'');if(s.includes(','))s=s.replace(/\./g,'').replace(',','.');if(!/^\d+(\.\d{1,2})?$/.test(s))throw Error('Informe um valor positivo, como 150,90');const n=Math.round(Number(s)*100);if(!Number.isSafeInteger(n)||n>1e12)throw Error('Valor fora do limite');return n;}
export function validDate(s){if(!/^\d{4}-\d{2}-\d{2}$/.test(s))return false;const d=new Date(s+'T12:00:00Z');return !isNaN(d)&&d.toISOString().slice(0,10)===s;}
export function validate(e){if(e.dueDate!==undefined&&!validDate(e.dueDate))throw Error('Vencimento inválido');if(e.planId!==undefined&&(typeof e.planId!=='string'||!e.planId||e.planId.length>100))throw Error('Referência de compromisso inválida');if(e.installment!==undefined&&(!Number.isInteger(e.installment)||e.installment<1||e.installment>1200))throw Error('Número da parcela inválido');if(e.installmentTotal!=null&&(!Number.isInteger(e.installmentTotal)||e.installmentTotal<e.installment||e.installmentTotal>600))throw Error('Total de parcelas inválido');if(!e.description?.trim()||e.description.length>200)throw Error('Descrição obrigatória, até 200 caracteres');if(!Object.keys(categories).includes(e.type))throw Error('Tipo inválido');if(!categories[e.type].includes(e.category))throw Error('Categoria incompatível com o tipo');if(!Number.isSafeInteger(e.amount)||e.amount<=0||e.amount>1e12)throw Error('Valor deve ser maior que zero');if(!validDate(e.date)||!/^\d{4}-(0[1-9]|1[0-2])$/.test(e.competence))throw Error('Data ou competência inválida');if(!['pago','pendente'].includes(e.status))throw Error('Situação inválida');if(!accounts.includes(e.account))throw Error('Conta inválida');if(e.type==='transferencia'&&(!accounts.includes(e.destination)||e.account===e.destination))throw Error('Selecione uma conta de destino diferente');return e;}
export const sign=e=>e.type==='receita'?1:e.type==='despesa'?-1:0;
export function summary(entries,month,basis='date',paidOnly=true){const selected=entries.filter(e=>e[basis].startsWith(month)&&(!paidOnly||e.status==='pago'));const income=selected.filter(e=>e.type==='receita').reduce((s,e)=>s+e.amount,0),expense=selected.filter(e=>e.type==='despesa').reduce((s,e)=>s+e.amount,0);return {selected,income,expense,result:income-expense};}
export function opening(entries,month){return entries.filter(e=>e.status==='pago'&&e.date<month+'-01').reduce((s,e)=>s+sign(e)*e.amount,0);}
export const fingerprint=e=>JSON.stringify([e.date,e.competence,e.description.trim().toLocaleLowerCase('pt-BR'),e.type,e.category,e.amount,e.status,e.account,e.destination||'']);
export function mergeImport(existing,incoming){const seen=new Set(existing.map(fingerprint)),ids=new Set(existing.map(e=>e.id));const added=[];let duplicates=0;for(const e of incoming){validate(e);if(seen.has(fingerprint(e))){duplicates++;continue;}if(ids.has(e.id))throw Error('Um ID já existe com dados diferentes. Revise a planilha antes de importar.');seen.add(fingerprint(e));ids.add(e.id);added.push(e);}return {entries:[...existing,...added],added:added.length,duplicates};}
